       ("Start import","Старт імпорт"),("More models","Мор моделз"),("Effort","Еффорт"),("Billing","Біллінг"),
       ("Add files or photos","Ед файлз ор фоутоуз"),("Memory","Мемморі"),
       ("Artifacts","Артефакти"),("Projects","Проджектс"),("Slides","Слайдз"),("Docs","Докс"),("Sonnet","Соннет"),("Haiku","Хайку"),("Opus","Опус"),("Fable","Фейбл"),
